        with pytest.raises(TaskNotFoundError):
            svc.set_priority(999, TaskPriority.LOW)


class TestSetDueAt:
    def test_set_due_at(self, svc):
        task = svc.create("task")
        due = NOW + timedelta(days=7)
        updated = svc.set_due_at(task.id, due)
        assert updated.due_at == due

    def test_clear_due_at(self, svc):
        due = NOW + timedelta(days=7)
        task = svc.create("task", due_at=due)
        updated = svc.set_due_at(task.id, None)
        assert updated.due_at is None

    def test_set_due_at_naive_raises(self, svc):
        task = svc.create("task")
        with pytest.raises(ValueError, match="timezone-aware"):
            svc.set_due_at(task.id, datetime(2025, 12, 1))

    def test_set_due_at_not_found(self, svc):
        with pytest.raises(TaskNotFoundError):
            svc.set_due_at(999, NOW)


class TestTags:
    def test_add_tags(self, svc):
        task = svc.create("task")
        updated = svc.add_tags(task.id, ["python", "flask"])
        assert {t.name for t in updated.tags} == {"python", "flask"}

    def test_add_tags_deduplicates(self, svc):
        task = svc.create("task", tags=["python"])
        updated = svc.add_tags(task.id, ["Python", "flask"])
        assert {t.name for t in updated.tags} == {"python", "flask"}

    def test_add_tags_not_found(self, svc):
        with pytest.raises(TaskNotFoundError):
            svc.add_tags(999, ["tag"])

    def test_remove_tag(self, svc):
        task = svc.create("task", tags=["python", "flask"])
        updated = svc.remove_tag(task.id, "python")
        assert [t.name for t in updated.tags] == ["flask"]

    def test_remove_tag_not_attached(self, svc):
        task = svc.create("task", tags=["python"])
        with pytest.raises(ValueError, match="not attached"):
            svc.remove_tag(task.id, "flask")

    def test_remove_tag_not_found(self, svc):
        with pytest.raises(TaskNotFoundError):
            svc.remove_tag(999, "tag")

